import math

P, Q, R = 0.10, 0.20, 0.05


def euler_rates(phi, theta, p, q, r):
    roll_rate = p + q * math.sin(phi) * math.tan(theta) + r * math.cos(phi) * math.tan(theta)
    pitch_rate = q * math.cos(phi) - r * math.sin(phi)
    yaw_rate = (q * math.sin(phi) + r * math.cos(phi)) / math.cos(theta)
    return (roll_rate, pitch_rate, yaw_rate)


