import math


def roll_error_quat(deg):
    h = math.radians(deg) / 2.0
    return (math.cos(h), math.sin(h), 0.0, 0.0)


def norm_of(v):
    return math.sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2])


def rotation_vector(e):
    norm = norm_of(e[1:])
    if norm < 1e-9:
        return (0.0, 0.0, 0.0)
    angle = 2.0 * math.atan2(norm, e[0])
    return tuple(angle * c / norm for c in e[1:])


def small_angle(e):
    return tuple(2.0 * c for c in e[1:])


for deg in (5.0, 90.0, 175.0):
    e = roll_error_quat(deg)
    print(deg, "exact_rad", round(norm_of(rotation_vector(e)), 4), "shortcut_rad", round(norm_of(small_angle(e)), 4))

import math

IXX = 0.011
KP_RATE = 40.0
DT = 0.001
STEPS = 800
TAU_MOTOR = 0.030
RATE_SP = 3.0


def motor_step(f, f_cmd):
    return f + (f_cmd - f) * (DT / TAU_MOTOR)


def overshoot(peak, rate_sp):
    return max(0.0, peak / rate_sp - 1.0)


def run(lag):
    rate, torque, peak = 0.0, 0.0, 0.0
    for _ in range(STEPS):
        cmd = IXX * KP_RATE * (RATE_SP - rate)
        torque = motor_step(torque, cmd) if lag else cmd
        rate += torque / IXX * DT
        peak = max(peak, rate)
    return peak


for name, lag in (("ideal", False), ("with_lag", True)):
    peak = run(lag)
    print(name, "peak_rate", round(peak, 4), "overshoot", round(overshoot(peak, RATE_SP), 4))

