def naive_deadband(s):
    if -DEADBAND < s < DEADBAND:
        return 0.0
    return s


def deadband(s):
    if abs(s) < DEADBAND:
        return 0.0
    return (s - math.copysign(DEADBAND, s)) / (1.0 - DEADBAND)


for s in (0.04, 0.051, 0.3, 1.0):
    print("stick", s, "naive_deg", round(MAX_ANGLE * naive_deadband(s), 4),
