STICK_EPS = 0.02
KP_POS = 1.0
MAX_SPEED = 8.0
DT = 0.02
STEPS = 500
STICK_STEPS = 150


def goal_of(target, x):
    return x if target is None else target


def update_target(target, x, stick):
    if abs(stick) > STICK_EPS:
        return None
    return target if target is not None else x


def fly(latching):
    x, target = 0.0, 0.0
    for i in range(STEPS):
        stick = 1.0 if i < STICK_STEPS else 0.0
        if latching:
            target = update_target(target if i else None, x, stick)
        if stick != 0.0:
            v = MAX_SPEED * stick
        else:
            v = min(MAX_SPEED, max(-MAX_SPEED, KP_POS * (goal_of(target, x) - x)))
        x += v * DT
    return x


