import math

import numpy as np

G = 9.81
KP_VEL = 2.0
DT = 0.02
STEPS = 1500
NOISE_SIGMA = 0.04


def noisy_command(kp_pos, target, x, noise):
    return kp_pos * (target - (x + noise))


def rms_tilt(tilts):
    return math.sqrt(sum(t * t for t in tilts) / len(tilts))


def run(kp_pos):
    rng = np.random.default_rng(11)
    x, v, tilts, radii = 0.0, 0.0, [], []
    for _ in range(STEPS):
        noise = float(rng.normal(0.0, NOISE_SIGMA))
        v_sp = noisy_command(kp_pos, 0.0, x, noise)
        a = KP_VEL * (v_sp - v)
        tilts.append(math.degrees(math.atan2(a, G)))
        v += a * DT
        x += v * DT
        radii.append(abs(x))
    return rms_tilt(tilts), math.sqrt(sum(r * r for r in radii) / len(radii))


for name, kp_pos in (("gentle", 0.6), ("firm", 2.5)):
    tilt, radius = run(kp_pos)
    print(name, "rms_tilt_deg", round(tilt, 4), "rms_radius_m", round(radius, 4))

