def next_phase(phase, x, t_in_phase, mode):
    if mode in ("return", "land"):
        if phase == "return" and abs(x) < ARRIVE_RADIUS:
            return "landed"
        return "return"
    if phase == "outbound" and abs(WAYPOINT - x) < ARRIVE_RADIUS:
        return "hold"
    if phase == "hold" and t_in_phase >= HOLD_SECONDS:
        return "return"
    if phase == "return" and abs(x) < ARRIVE_RADIUS:
        return "landed"
    return phase


